# §2.1 滑台定位 — 丝杆滑台控制

## 一、核心参数计算

| 参数 | 值 |
|------|------|
| 导程 (lead) | 10 mm/rev |
| 驱动器细分数 | 400 pulses/rev |
| 每脉冲位移 | 10 / 400 = **0.025 mm/pulse** |

---

## 二、w10-s2-calSliderStroke.ino — 测算滑台行程

```cpp
/*
 * w10-s2-calSliderStroke.ino
 * 测算丝杆滑台的行程（脉冲数表示）
 * 
 * 参数：
 *   导程 = 10 mm/rev
 *   细分数 = 400 pulses/rev
 *   每脉冲位移 = 0.025 mm
 */

const int STEP_PIN = 2;
const int DIR_PIN  = 3;

const float LEAD        = 10.0;    // 导程 mm/rev
const int   MICROSTEPS  = 400;     // 细分数 pulses/rev
const float MM_PER_PULSE = LEAD / MICROSTEPS;  // 0.025 mm/pulse

// ===== 请根据实际滑台修改行程 =====
const float STROKE_MM = 200.0;     // 滑台物理行程 (mm)，需实测
// =================================

const long STROKE_PULSES = (long)(STROKE_MM / MM_PER_PULSE);

void setup() {
  pinMode(STEP_PIN, OUTPUT);
  pinMode(DIR_PIN,  OUTPUT);
  Serial.begin(9600);

  Serial.println("===== 滑台行程测算 =====");
  Serial.print("导程: ");       Serial.print(LEAD);       Serial.println(" mm/rev");
  Serial.print("细分数: ");     Serial.print(MICROSTEPS);  Serial.println(" pulses/rev");
  Serial.print("每脉冲位移: "); Serial.print(MM_PER_PULSE, 4); Serial.println(" mm/pulse");
  Serial.print("物理行程: ");   Serial.print(STROKE_MM);   Serial.println(" mm");
  Serial.print("行程脉冲数: "); Serial.print(STROKE_PULSES); Serial.println(" pulses");
  Serial.println("========================");

  // 演示：从起点走到终点再返回
  digitalWrite(DIR_PIN, HIGH);
  moveSteps(STROKE_PULSES, 1000);  // 正向走完全程，1000μs/脉冲
  delay(1000);

  digitalWrite(DIR_PIN, LOW);
  moveSteps(STROKE_PULSES, 1000);  // 反向走完全程
}

